export function detectFailedJob(rows, now = Date.now()) {
  const latest = new Map();
  for (const r of rows) {
    const key = r.taskName || r.job || `${r.provider || 'executor'}:${r.cwd || '不明'}`;
    if (!latest.has(key) || new Date(r.t) >= new Date(latest.get(key).t)) latest.set(key, r);
  }
  return [...latest].flatMap(([id, r]) => {
    if (!Number.isFinite(new Date(r.t).getTime()) || r.running || r.status == null || Number(r.status) === 0 || ['ok', 'success', 'fallback', 'cooldown', 'deferred'].includes(String(r.status).toLowerCase()) || [267009, 267011].includes(Number(r.status))) return [];
    if (!Number.isFinite(Number(r.status)) && !/^(?:error|failed|failure|unusable|no-cheap-executor|http_[45]\d\d)$/.test(String(r.status))) return [];
    return [item('failed_job', id, `実行失敗: ${id}`, r.location || r.cwd || id, age(r.t, now), 'Codexで原因を調査して安全に再実行',
      `直近の終了コード ${r.status}`, { cwd: localPath(r.cwd), taskName: r.taskName, eventTime: r.t })];
  });

const ledger = path.join(home, '.claude', 'executor-usage.jsonl');
function appendAttempt(info, usage = {}) {
  if (info.candidate.provider === 'gemini') {
    const measured = geminiUsage({ usage });
    try {
      recordGeminiUsage({
        model: info.candidate.model,
        ...measured,
        source: 'llm-ask',
        status: info.status,
        attempt: info.attempt,
        failover: info.failover,
        secs: Number(info.secs.toFixed(3)),
      }, { home, usageFile: ledger });
    } catch {}
    return;
  }
  const rec = { t: new Date().toISOString(), provider: info.candidate.provider, model: info.candidate.model, in: usage.prompt_tokens || 0, out: usage.completion_tokens || 0, secs: Number(info.secs.toFixed(3)), status: info.status, attempt: info.attempt, failover: info.failover };
  try { fs.mkdirSync(path.dirname(ledger), { recursive: true }); fs.appendFileSync(ledger, JSON.stringify(rec) + '\n'); } catch {}
}

try {
  const result = await callWithFallback({
    start,
    chain: args.includes('--no-fallback') ? [] : FALLBACK_CHAIN,
    allowGatewayFallback: !args.includes('--no-fallback'),
    payloadFor(candidate) {
      const P = PROVIDERS[candidate.provider]; const key = loadKey(candidate.provider);
      if (!P || !key) return null;
      const payload = { model: candidate.model || P.model, messages, max_tokens: maxTok, stream: false };
      if (P.special === 'kimi') Object.assign(payload, { reasoning_effort: 'none', temperature: 0.6 });
      return { url: P.base, init: { method: 'POST', headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', ...(P.extraHeaders || {}) }, body: JSON.stringify(payload) } };
    },
    async onAttempt(info) {
      let usage = {};
      if (info.status === 'ok') usage = (await info.response.clone().json().catch(() => ({}))).usage || {};
      appendAttempt(info, usage);
    },
    onFailover({ from, to, reason }) { console.error(`[failover] ${from.provider}:${from.model} ${reason} → ${to.provider}:${to.model}`); },
  });

for (let attempt = 0; attempt < 3; attempt++) {
  lastAttempt = attempt;
  const began = Date.now();
  let response;
  let status;
  let detail = '';
  try {
    response = await fetchImpl(request.url, request.init);
    status = response.status;
    // 残量ヘッダを下限として記録する。次に同じ provider を選ぶ時、この値で事前に絞れる。
    if (useBudget && response?.headers && noteResponse(budgetStore, candidate.provider, response.headers, now())) writeBudget(budgetPath, budgetStore);
    if (response.ok) {
      if (validateResponse) {
        const json = await response.clone().json().catch(() => null);
        const validation = await validateResponse(json, candidate);
        if (validation !== true) {
          const validationReason = typeof validation === 'string' ? validation : 'unusable response';
          lastReason = `unusable: ${validationReason}`;
          attempted++;
          await onAttempt?.({ candidate, attempt, status: 'unusable', response, reason: lastReason, secs: (Date.now() - began) / 1000, failover: candidate.provider !== start.provider });
          break;
        }
      }
      await onAttempt?.({ candidate, attempt, status: 'ok', response, secs: (Date.now() - began) / 1000, failover: candidate.provider !== start.provider });
      clearCooldown(candidate.provider);
      saveCooldowns();
      return { response, candidate, failover: candidate.provider !== start.provider, attempt };
    }
    detail = (await response.clone().text().catch(() => '')).slice(0, 400);
    lastReason = `HTTP${status}${detail ? `: ${detail}` : ''}`;
  } catch (error) {
    lastReason = `network: ${error?.message || String(error)}`;
  }
  attempted++;
  await onAttempt?.({ candidate, attempt, status: statusName(status), response, reason: lastReason, secs: (Date.now() - began) / 1000, failover: candidate.provider !== start.provider });
  // groq の通常429の本文には `https://console.groq.com/settings/billing` が含まれるため、
  // 素の `billing` で判定すると日次上限(TPD)を恒久障害と誤判定する。恒久障害の文面だけを拾う。
  const permanentBilling = status === 429 && /prepayment credits are depleted|insufficient_quota|exceeded your current quota/i.test(detail);
  setCooldown(candidate.provider, status, response, permanentBilling);

  const kind = classifyFailure(status);
  if (permanentBilling || kind !== 'retry' || attempt === 2) break;
  const specified = retryAfterMs(response);
  if (specified != null && specified > 60000) break;
  await sleepImpl(specified ?? 1000 * 2 ** attempt);
